window.STUDY_DATA = {"decks": [{"id": 1, "name": "Default"}, {"id": 1793286881161, "name": "многообразия"}], "cards": [{"id": "1793287075604", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Гладкие подмногообразия аффинного пространства. Определение. (Билет 1.1)", "answerHtml": " Подмногообразием размерности k области U аффинного пространства R^n (с координатами x^1, ..., x^n) называется подмножество M ⊂ U, которое в окрестности любой точки a области U является множеством решений системы из n − k уравнений f_1(x^1, ..., x^n) = 0, ..., f_{n−k}(x^1, ..., x^n) = 0, для которой ранг матрицы (∂f_i/∂x^j(a)), i = 1, ..., n − k, j = 1, ..., n, равен n − k.", "questionText": "Гладкие подмногообразия аффинного пространства. Определение. (Билет 1.1)", "answerText": "Подмногообразием размерности k области U аффинного пространства R^n (с координатами x^1, ..., x^n) называется подмножество M ⊂ U, которое в окрестности любой точки a области U является множеством решений системы из n − k уравнений f_1(x^1, ..., x^n) = 0, ..., f_{n−k}(x^1, ..., x^n) = 0, для которой ранг матрицы (∂f_i/∂x^j(a)), i = 1, ..., n − k, j = 1, ..., n, равен n − k.", "ticket": "1", "section": "1.1", "title": "Гладкие подмногообразия аффинного пространства. Определение."}, {"id": "1793287075605", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Гладкие подмногообразия аффинного пространства. Примеры. (Билет 1.1)", "answerHtml": "Интервал не подмногообразие <br>Окружность подмногообразие", "questionText": "Гладкие подмногообразия аффинного пространства. Примеры. (Билет 1.1)", "answerText": "Интервал не подмногообразие \nОкружность подмногообразие", "ticket": "1", "section": "1.1", "title": "Гладкие подмногообразия аффинного пространства. Примеры."}, {"id": "1793287075606", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Задание подмногообразий системами уравнений. (Билет 1.2)", "answerHtml": "Мысль1: Система уравнений f_1 = 0, ..., f_{n−k} = 0 на области U ⊂ R^n может быть задана отображением F: U → R^{n−k}. Множество решений этой системы — это прообраз нуля F^{-1}(0). Условие невырожденности системы (ранг матрицы Якоби = n−k) совпадает с условием невырожденности отображения F. <br><br>Мысль2: Если M^k — k-мерное подмногообразие в R^n, задаваемое такой системой, то для любой точки из M^k существует ее окрестность, в которой некоторые n−k координат из x^1, ..., x^n гладко выражаются через остальные k координат. То есть локально подмногообразие M^k является графиком гладкого отображения из R^k в R^{n−k}.<br>", "questionText": "Задание подмногообразий системами уравнений. (Билет 1.2)", "answerText": "Мысль1: Система уравнений f_1 = 0, ..., f_{n−k} = 0 на области U ⊂ R^n может быть задана отображением F: U → R^{n−k}. Множество решений этой системы — это прообраз нуля F^{-1}(0). Условие невырожденности системы (ранг матрицы Якоби = n−k) совпадает с условием невырожденности отображения F. \n\nМысль2: Если M^k — k-мерное подмногообразие в R^n, задаваемое такой системой, то для любой точки из M^k существует ее окрестность, в которой некоторые n−k координат из x^1, ..., x^n гладко выражаются через остальные k координат. То есть локально подмногообразие M^k является графиком гладкого отображения из R^k в R^{n−k}.", "ticket": "1", "section": "1.2", "title": "Задание подмногообразий системами уравнений."}, {"id": "1793287075607", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Локальные параметризации подмногообразий. (Билет 1.3)", "answerHtml": " Подмногообразие в R^n локально является образом невырожденного отображения Ψ области пространства R^k в пространство R^n. Отображение Ψ(x) = (y^1(x), ..., y^N(x)) невырождено в прообразе a точки P: rk(∂y^i/∂x^j(a)) = k. Оно задает параметризацию, т.е. определяет локальные координаты на подмногообразии.", "questionText": "Локальные параметризации подмногообразий. (Билет 1.3)", "answerText": "Подмногообразие в R^n локально является образом невырожденного отображения Ψ области пространства R^k в пространство R^n. Отображение Ψ(x) = (y^1(x), ..., y^N(x)) невырождено в прообразе a точки P: rk(∂y^i/∂x^j(a)) = k. Оно задает параметризацию, т.е. определяет локальные координаты на подмногообразии.", "ticket": "1", "section": "1.3", "title": "Локальные параметризации подмногообразий."}, {"id": "1793287075608", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Локальные параметризации подмногообразий. Условие регулярности. (Билет 1.3)", "answerHtml": " Отображение Ψ: U → R^n (U ⊂ R^k, Ψ = (ψ_1, ..., ψ_n)) невырождено (регулярно) в точке x ∈ U, если матрица (∂ψ_i/∂x^j(x)), i = 1, ..., n, j = 1, ..., k, имеет максимально возможный ранг, равный min(k, n). Отображение Ψ невырождено, если оно невырождено во всех точках x ∈ U.", "questionText": "Локальные параметризации подмногообразий. Условие регулярности. (Билет 1.3)", "answerText": "Отображение Ψ: U → R^n (U ⊂ R^k, Ψ = (ψ_1, ..., ψ_n)) невырождено (регулярно) в точке x ∈ U, если матрица (∂ψ_i/∂x^j(x)), i = 1, ..., n, j = 1, ..., k, имеет максимально возможный ранг, равный min(k, n). Отображение Ψ невырождено, если оно невырождено во всех точках x ∈ U.", "ticket": "1", "section": "1.3", "title": "Локальные параметризации подмногообразий. Условие регулярности."}, {"id": "1793287075609", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Теорема об образе. (Билет 1.4)", "answerHtml": " Пусть Ψ: U → V — гладкое отображение окрестности U точки a в R^k в окрестность V точки b в R^n, Ψ(x) = (ψ_1(x), ..., ψ_n(x)), Ψ(a) = b, и пусть rk dΨ|a = rk (∂ψ_i/∂x^j(a)) = k. Тогда существует такая окрестность U' точки a в R^k, что Ψ(U') — гладкое подмногообразие (размерности k) некоторой окрестности V' точки b в R^n.", "questionText": "Теорема об образе. (Билет 1.4)", "answerText": "Пусть Ψ: U → V — гладкое отображение окрестности U точки a в R^k в окрестность V точки b в R^n, Ψ(x) = (ψ_1(x), ..., ψ_n(x)), Ψ(a) = b, и пусть rk dΨ|a = rk (∂ψ_i/∂x^j(a)) = k. Тогда существует такая окрестность U' точки a в R^k, что Ψ(U') — гладкое подмногообразие (размерности k) некоторой окрестности V' точки b в R^n.", "ticket": "1", "section": "1.4", "title": "Теорема об образе."}, {"id": "1793287075610", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Теорема об обратном отображении. (Билет 1.4)", "answerHtml": " Пусть Φ: U → R^n — гладкое отображение окрестности точки a в пространстве R^n, Φ(x) = (φ_1(x), ..., φ_n(x)), Φ(a) = b, и пусть det(∂φ_i/∂x^j(a)) ≠ 0. Тогда существует такая (вообще говоря, меньшая, чем U) окрестность U' точки a в пространстве R^n, что Φ является взаимно однозначным отображением U' на окрестность Φ(U') точки b = Φ(a) и при этом обратное отображение Φ^{−1}: Φ(U') → U' также является бесконечно дифференцируемым.", "questionText": "Теорема об обратном отображении. (Билет 1.4)", "answerText": "Пусть Φ: U → R^n — гладкое отображение окрестности точки a в пространстве R^n, Φ(x) = (φ_1(x), ..., φ_n(x)), Φ(a) = b, и пусть det(∂φ_i/∂x^j(a)) ≠ 0. Тогда существует такая (вообще говоря, меньшая, чем U) окрестность U' точки a в пространстве R^n, что Φ является взаимно однозначным отображением U' на окрестность Φ(U') точки b = Φ(a) и при этом обратное отображение Φ^{−1}: Φ(U') → U' также является бесконечно дифференцируемым.", "ticket": "1", "section": "1.4", "title": "Теорема об обратном отображении."}, {"id": "1793287075611", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Координатные карты. (Билет 2.1)", "answerHtml": " Картой размерности k на топологическом пространстве X называется пара (U, Ψ), состоящая из открытого подмножества U ⊂ X и гомеоморфизма Ψ: U → V множества U на открытое множество V ⊂ R^k.", "questionText": "Координатные карты. (Билет 2.1)", "answerText": "Картой размерности k на топологическом пространстве X называется пара (U, Ψ), состоящая из открытого подмножества U ⊂ X и гомеоморфизма Ψ: U → V множества U на открытое множество V ⊂ R^k.", "ticket": "2", "section": "2.1", "title": "Координатные карты."}, {"id": "1793287075612", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Атласы. (Билет 2.1)", "answerHtml": " Атласом размерности k на топологическом пространстве X называется набор карт (U_α, Ψ_α), который покрывает все X (т.е. ∪U_α = X) и каждые две карты которого согласованы.", "questionText": "Атласы. (Билет 2.1)", "answerText": "Атласом размерности k на топологическом пространстве X называется набор карт (U_α, Ψ_α), который покрывает все X (т.е. ∪U_α = X) и каждые две карты которого согласованы.", "ticket": "2", "section": "2.1", "title": "Атласы."}, {"id": "1793287075613", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Замены координат (согласованность карт). (Билет 2.1)", "answerHtml": " Карты (U_1, Ψ_1) и (U_2, Ψ_2) на топологическом пространстве X согласованы, если отображения Ψ_2 ∘ Ψ_1^{−1} и Ψ_1 ∘ Ψ_2^{−1} — гладкие.", "questionText": "Замены координат (согласованность карт). (Билет 2.1)", "answerText": "Карты (U_1, Ψ_1) и (U_2, Ψ_2) на топологическом пространстве X согласованы, если отображения Ψ_2 ∘ Ψ_1^{−1} и Ψ_1 ∘ Ψ_2^{−1} — гладкие.", "ticket": "2", "section": "2.1", "title": "Замены координат (согласованность карт)."}, {"id": "1793287075614", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Гладкие многообразия. (Билет 2.2)", "answerHtml": " Гладким многообразием размерности k называется хаусдорфово топологическое пространство M^k со счетной базой вместе с классом эквивалентности k-мерных атласов на нем.", "questionText": "Гладкие многообразия. (Билет 2.2)", "answerText": "Гладким многообразием размерности k называется хаусдорфово топологическое пространство M^k со счетной базой вместе с классом эквивалентности k-мерных атласов на нем.", "ticket": "2", "section": "2.2", "title": "Гладкие многообразия."}, {"id": "1793287075615", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Гладкие функции на многообразии. (Билет 2.3)", "answerHtml": " Говорят, что функция f: U → R, заданная на области U гладкого многообразия M, гладкая, если для любой карты (U_α, Ψ_α) из атласа, задающего гладкую структуру на M, функция f ∘ Ψ_α^{−1} является гладкой функцией на области Ψ_α(U ∩ U_α) аффинного пространства R^k.", "questionText": "Гладкие функции на многообразии. (Билет 2.3)", "answerText": "Говорят, что функция f: U → R, заданная на области U гладкого многообразия M, гладкая, если для любой карты (U_α, Ψ_α) из атласа, задающего гладкую структуру на M, функция f ∘ Ψ_α^{−1} является гладкой функцией на области Ψ_α(U ∩ U_α) аффинного пространства R^k.", "ticket": "2", "section": "2.3", "title": "Гладкие функции на многообразии."}, {"id": "1793287075616", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Гладкие отображения многообразий. (Билет 2.3)", "answerHtml": " Непрерывное отображение f: M^k → N^l называется гладким, если для любой точки x ∈ M^k, любой карты Ψ: U → V ⊂ R^k, содержащей x, и любой карты Ψ': U' → V' ⊂ R^l, содержащей f(x), отображение Ψ' ∘ f ∘ Ψ^{−1}: Ψ(U ∩ f^{−1}(U')) → V' является гладким.", "questionText": "Гладкие отображения многообразий. (Билет 2.3)", "answerText": "Непрерывное отображение f: M^k → N^l называется гладким, если для любой точки x ∈ M^k, любой карты Ψ: U → V ⊂ R^k, содержащей x, и любой карты Ψ': U' → V' ⊂ R^l, содержащей f(x), отображение Ψ' ∘ f ∘ Ψ^{−1}: Ψ(U ∩ f^{−1}(U')) → V' является гладким.", "ticket": "2", "section": "2.3", "title": "Гладкие отображения многообразий."}, {"id": "1793287075617", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Диффеоморфизмы. (Билет 2.3)", "answerHtml": " Отображение f: M^k → N^l называется диффеоморфизмом, если оно гладкое и имеет гладкое обратное (т. е. существует такое гладкое отображение g: N^l → M^k, что g ∘ f = id{M^k}, f ∘ g = id_{N^l}).", "questionText": "Диффеоморфизмы. (Билет 2.3)", "answerText": "Отображение f: M^k → N^l называется диффеоморфизмом, если оно гладкое и имеет гладкое обратное (т. е. существует такое гладкое отображение g: N^l → M^k, что g ∘ f = id{M^k}, f ∘ g = id_{N^l}).", "ticket": "2", "section": "2.3", "title": "Диффеоморфизмы."}, {"id": "1793287075618", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Касательные векторы как классы эквивалентности гладких кривых. (Билет 2.4)", "answerHtml": " Две гладкие кривые γ_1(t) и γ_2(t) на многообразии M^n (γ_i(0) = a, i = 1, 2) эквивалентны, если в некоторой локальной системе координат ρ(γ_1(t), γ_2(t)) = o(t). Касательным вектором в точке a многообразия M^n называется класс эквивалентности кривых на M^n, проходящих через точку a.", "questionText": "Касательные векторы как классы эквивалентности гладких кривых. (Билет 2.4)", "answerText": "Две гладкие кривые γ_1(t) и γ_2(t) на многообразии M^n (γ_i(0) = a, i = 1, 2) эквивалентны, если в некоторой локальной системе координат ρ(γ_1(t), γ_2(t)) = o(t). Касательным вектором в точке a многообразия M^n называется класс эквивалентности кривых на M^n, проходящих через точку a.", "ticket": "2", "section": "2.4", "title": "Касательные векторы как классы эквивалентности гладких кривых."}, {"id": "1793287075619", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Координатное определение касательного вектора. (Билет 2.5)", "answerHtml": " Касательным вектором в точке a многообразия M^n называется набор чисел (координат вектора или его компонент) (u^1, ..., u^n), определяемый для каждой системы локальных координат (x^1, ..., x^n) на M^n и меняющийся при замене координат на (\\tilde{x}^1, ..., \\tilde{x}^n) по правилу \\tilde{u}^i = (∂\\tilde{x}^i/∂x^j)(a) · u^j.", "questionText": "Координатное определение касательного вектора. (Билет 2.5)", "answerText": "Касательным вектором в точке a многообразия M^n называется набор чисел (координат вектора или его компонент) (u^1, ..., u^n), определяемый для каждой системы локальных координат (x^1, ..., x^n) на M^n и меняющийся при замене координат на (\\tilde{x}^1, ..., \\tilde{x}^n) по правилу \\tilde{u}^i = (∂\\tilde{x}^i/∂x^j)(a) · u^j.", "ticket": "2", "section": "2.5", "title": "Координатное определение касательного вектора."}, {"id": "1793287075620", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Касательные векторы как операторы дифференцирования. (Билет 2.6)", "answerHtml": " Касательным вектором в точке a многообразия M^n называется дифференцирование на алгебре E_{M^n, a} ростков функций на M^n в точке a, т. е. линейный функционал u: E_{M^n, a} → R, удовлетворяющий правилу Лейбница u(fg) = g(a)uf + f(a)ug.", "questionText": "Касательные векторы как операторы дифференцирования. (Билет 2.6)", "answerText": "Касательным вектором в точке a многообразия M^n называется дифференцирование на алгебре E_{M^n, a} ростков функций на M^n в точке a, т. е. линейный функционал u: E_{M^n, a} → R, удовлетворяющий правилу Лейбница u(fg) = g(a)uf + f(a)ug.", "ticket": "2", "section": "2.6", "title": "Касательные векторы как операторы дифференцирования."}, {"id": "1793287075621", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Эквивалентность определений касательного вектора. (Билет 2.6)", "answerHtml": " Касательный вектор в смысле первых двух определений (через кривые и координаты) является касательным вектором в смысле определения через дифференцирования. Обратное утверждение доказывается с помощью леммы Адамара.", "questionText": "Эквивалентность определений касательного вектора. (Билет 2.6)", "answerText": "Касательный вектор в смысле первых двух определений (через кривые и координаты) является касательным вектором в смысле определения через дифференцирования. Обратное утверждение доказывается с помощью леммы Адамара.", "ticket": "2", "section": "2.6", "title": "Эквивалентность определений касательного вектора."}, {"id": "1793287075622", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Касательное пространство в точке, его базис. (Билет 2.7)", "answerHtml": " Векторы ∂/∂x^i, i = 1, ..., n, образуют базис касательного пространства T_a M^n (в смысле определения через дифференцирования). В смысле координатного определения это векторы (1, 0, ..., 0), (0, 1, ..., 0), ..., (0, 0, ..., 1).", "questionText": "Касательное пространство в точке, его базис. (Билет 2.7)", "answerText": "Векторы ∂/∂x^i, i = 1, ..., n, образуют базис касательного пространства T_a M^n (в смысле определения через дифференцирования). В смысле координатного определения это векторы (1, 0, ..., 0), (0, 1, ..., 0), ..., (0, 0, ..., 1).", "ticket": "2", "section": "2.7", "title": "Касательное пространство в точке, его базис."}, {"id": "1793287075623", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Дифференциал гладкого отображения многообразий. (Билет 2.8)", "answerHtml": " Отображение из касательного пространства T_a M^n в касательное пространство T_{F(a)} N^s, определенное через эквивалентность кривых, называется дифференциалом отображения F в точке a и обозначается обычно через dF|a.", "questionText": "Дифференциал гладкого отображения многообразий. (Билет 2.8)", "answerText": "Отображение из касательного пространства T_a M^n в касательное пространство T_{F(a)} N^s, определенное через эквивалентность кривых, называется дифференциалом отображения F в точке a и обозначается обычно через dF|a.", "ticket": "2", "section": "2.8", "title": "Дифференциал гладкого отображения многообразий."}, {"id": "1793287075624", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Дифференциал гладкого отображения многообразий. Координатная запись. (Билет 2.8)", "answerHtml": " Образом вектора u = (u^1, ..., u^n) ∈ T_a M^n является вектор v = (v^1, ..., v^s) ∈ T{F(a)} N^s, компоненты которого задаются формулами v^i = (∂f_i/∂x^j)(a)u^j, i = 1, ..., s. Матрица (∂f_i/∂x^j)(a) называется матрицей Якоби.", "questionText": "Дифференциал гладкого отображения многообразий. Координатная запись. (Билет 2.8)", "answerText": "Образом вектора u = (u^1, ..., u^n) ∈ T_a M^n является вектор v = (v^1, ..., v^s) ∈ T{F(a)} N^s, компоненты которого задаются формулами v^i = (∂f_i/∂x^j)(a)u^j, i = 1, ..., s. Матрица (∂f_i/∂x^j)(a) называется матрицей Якоби.", "ticket": "2", "section": "2.8", "title": "Дифференциал гладкого отображения многообразий. Координатная запись."}, {"id": "1793287075625", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Дифференциал гладкого отображения многообразий. Свойства. (Билет 2.8)", "answerHtml": " Дифференциал отображения dF|a: T_a M^n → T{F(a)} N^s является линейным отображением.", "questionText": "Дифференциал гладкого отображения многообразий. Свойства. (Билет 2.8)", "answerText": "Дифференциал отображения dF|a: T_a M^n → T{F(a)} N^s является линейным отображением.", "ticket": "2", "section": "2.8", "title": "Дифференциал гладкого отображения многообразий. Свойства."}, {"id": "1793287075626", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Пространство касательного расслоения. (Билет 2.9)", "answerHtml": " Пусть TM^n — объединение T_a M^n касательных пространств во всех точках a ∈ M^n. Множество TM^n состоит из всех пар вида (a, u), где a ∈ M^n, u ∈ T_a M^n.", "questionText": "Пространство касательного расслоения. (Билет 2.9)", "answerText": "Пусть TM^n — объединение T_a M^n касательных пространств во всех точках a ∈ M^n. Множество TM^n состоит из всех пар вида (a, u), где a ∈ M^n, u ∈ T_a M^n.", "ticket": "2", "section": "2.9", "title": "Пространство касательного расслоения."}, {"id": "1793287075627", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Пространство касательного расслоения. Его гладкая структура. (Билет 2.9)", "answerHtml": " Набор карт {(TU_α, Φ_α)} (где Φ_α: TU_α → R^{2n}, (a,u) → (x^1, ..., x^n, u^1, ..., u^n)) определяет (2n-мерный) атлас на TM^n, т. е. структуру 2n-мерного многообразия на нем.", "questionText": "Пространство касательного расслоения. Его гладкая структура. (Билет 2.9)", "answerText": "Набор карт {(TU_α, Φ_α)} (где Φ_α: TU_α → R^{2n}, (a,u) → (x^1, ..., x^n, u^1, ..., u^n)) определяет (2n-мерный) атлас на TM^n, т. е. структуру 2n-мерного многообразия на нем.", "ticket": "2", "section": "2.9", "title": "Пространство касательного расслоения. Его гладкая структура."}, {"id": "1793287075628", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Касательные ковекторы. (Билет 2.10)", "answerHtml": " Линейная функция на векторах называется ковектором. Ковекторы в точке a ∈ M^n образуют линейное пространство T_a^* M^n, двойственное к касательному пространству T_a M^n.", "questionText": "Касательные ковекторы. (Билет 2.10)", "answerText": "Линейная функция на векторах называется ковектором. Ковекторы в точке a ∈ M^n образуют линейное пространство T_a^* M^n, двойственное к касательному пространству T_a M^n.", "ticket": "2", "section": "2.10", "title": "Касательные ковекторы."}, {"id": "1793287075629", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Кокасательное пространство и его базис. (Билет 2.10)", "answerHtml": " В локальной системе координат (x^1, ..., x^n) на M^n векторы ∂/∂x^i образуют базис T_a M^n. Двойственный базис в T_a^* M^n состоит из дифференциалов координат dx^1, ..., dx^n (таких, что (dx^i, ∂/∂x^j) = δ_j^i).", "questionText": "Кокасательное пространство и его базис. (Билет 2.10)", "answerText": "В локальной системе координат (x^1, ..., x^n) на M^n векторы ∂/∂x^i образуют базис T_a M^n. Двойственный базис в T_a^* M^n состоит из дифференциалов координат dx^1, ..., dx^n (таких, что (dx^i, ∂/∂x^j) = δ_j^i).", "ticket": "2", "section": "2.10", "title": "Кокасательное пространство и его базис."}, {"id": "1793287075630", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Дифференциал гладкой функции как ковектор. (Билет 2.11)", "answerHtml": " Производная функции f вдоль кривой с касательным вектором v = (v^1, ..., v^n) равна скалярному произведению grad f(a) и v, что является линейной функцией от вектора v. Поэтому дифференциал функции в точке a — это линейная функция на касательном пространстве T_a M^n, то есть ковектор.", "questionText": "Дифференциал гладкой функции как ковектор. (Билет 2.11)", "answerText": "Производная функции f вдоль кривой с касательным вектором v = (v^1, ..., v^n) равна скалярному произведению grad f(a) и v, что является линейной функцией от вектора v. Поэтому дифференциал функции в точке a — это линейная функция на касательном пространстве T_a M^n, то есть ковектор.", "ticket": "2", "section": "2.11", "title": "Дифференциал гладкой функции как ковектор."}, {"id": "1793287075631", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Тензоры на векторных пространствах. (Билет 3.1)", "answerHtml": " Тензором типа (p, q) на векторном пространстве E называется полилинейная функция на E^* × ... × E^* × E × ... × E (p сомножителей E^* и q сомножителей E).", "questionText": "Тензоры на векторных пространствах. (Билет 3.1)", "answerText": "Тензором типа (p, q) на векторном пространстве E называется полилинейная функция на E^* × ... × E^* × E × ... × E (p сомножителей E^* и q сомножителей E).", "ticket": "3", "section": "3.1", "title": "Тензоры на векторных пространствах."}, {"id": "1793287075632", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Тензоры типа (r,s) на многообразии. (Билет 3.2)", "answerHtml": " Тензор T типа (p, q) в точке a многообразия M^n — это тензор (того же типа) на касательном пространстве T_a M^n к многообразию M^n в точке a.", "questionText": "Тензоры типа (r,s) на многообразии. (Билет 3.2)", "answerText": "Тензор T типа (p, q) в точке a многообразия M^n — это тензор (того же типа) на касательном пространстве T_a M^n к многообразию M^n в точке a.", "ticket": "3", "section": "3.2", "title": "Тензоры типа (r,s) на многообразии."}, {"id": "1793287075633", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Тензорные поля. (Билет 3.2)", "answerHtml": " Множество T^{(p,q)}M^n = ⋃_{x∈M^n} T_x^{(p,q)}M^n имеет естественную структуру гладкого многообразия и векторного расслоения над многообразием M^n.", "questionText": "Тензорные поля. (Билет 3.2)", "answerText": "Множество T^{(p,q)}M^n = ⋃_{x∈M^n} T_x^{(p,q)}M^n имеет естественную структуру гладкого многообразия и векторного расслоения над многообразием M^n.", "ticket": "3", "section": "3.2", "title": "Тензорные поля."}, {"id": "1793287075634", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Координатное представление тензоров. (Билет 3.3)", "answerHtml": " Локальные координаты x^1, ..., x^n в окрестности точки a определяют базис ∂/∂x^1, ..., ∂/∂x^n на касательном пространстве T_a M^n. Тем самым тензор T приобретает свои координаты (компоненты) T_{j_1...j_q}^{i_1...i_p} = T(dx^{i_1}, ..., dx^{i_p}, ∂/∂x^{j_1}, ..., ∂/∂x^{j_q}).", "questionText": "Координатное представление тензоров. (Билет 3.3)", "answerText": "Локальные координаты x^1, ..., x^n в окрестности точки a определяют базис ∂/∂x^1, ..., ∂/∂x^n на касательном пространстве T_a M^n. Тем самым тензор T приобретает свои координаты (компоненты) T_{j_1...j_q}^{i_1...i_p} = T(dx^{i_1}, ..., dx^{i_p}, ∂/∂x^{j_1}, ..., ∂/∂x^{j_q}).", "ticket": "3", "section": "3.3", "title": "Координатное представление тензоров."}, {"id": "1793287075635", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Закон преобразования компонент тензора при замене координат. (Билет 3.3)", "answerHtml": " Компоненты T_{j_1...j_q}^{i_1...i_p} в другой системе координат \\tilde{x}^1, ..., \\tilde{x}^n выражаются через его компоненты в координатах x^1, ..., x^n по формуле: \\tilde{T}{j_1...j_q}^{i_1...i_p} = T{j_1...j_q}^{i_1...i_p} (∂\\tilde{x}^{i_1}/∂x^{i_1}) ... (∂\\tilde{x}^{i_p}/∂x^{i_p}) (∂x^{i_1}/∂\\tilde{x}^{i_1}) ... (∂x^{i_p}/∂\\tilde{x}^{i_p}).", "questionText": "Закон преобразования компонент тензора при замене координат. (Билет 3.3)", "answerText": "Компоненты T_{j_1...j_q}^{i_1...i_p} в другой системе координат \\tilde{x}^1, ..., \\tilde{x}^n выражаются через его компоненты в координатах x^1, ..., x^n по формуле: \\tilde{T}{j_1...j_q}^{i_1...i_p} = T{j_1...j_q}^{i_1...i_p} (∂\\tilde{x}^{i_1}/∂x^{i_1}) ... (∂\\tilde{x}^{i_p}/∂x^{i_p}) (∂x^{i_1}/∂\\tilde{x}^{i_1}) ... (∂x^{i_p}/∂\\tilde{x}^{i_p}).", "ticket": "3", "section": "3.3", "title": "Закон преобразования компонент тензора при замене координат."}, {"id": "1793287075636", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Тензорное произведение. (Билет 3.4)", "answerHtml": " Тензорным произведением (или произведением) тензоров T и S называется тензор T ⊗ S типа (p_1 + p_2, q_1 + q_2), компоненты которого задаются формулой (T ⊗ S){j_1...j{q_1}...j_{q_1+q_2}}^{i_1...i_{p_1}...i_{p_1+p_2}} = T_{j_1...j_{q_1}}^{i_1...i_{p_1}} S_{j_{q_1+1}...j_{q_1+q_2}}^{i_{p_1+1}...i_{p_1+p_2}}.", "questionText": "Тензорное произведение. (Билет 3.4)", "answerText": "Тензорным произведением (или произведением) тензоров T и S называется тензор T ⊗ S типа (p_1 + p_2, q_1 + q_2), компоненты которого задаются формулой (T ⊗ S){j_1...j{q_1}...j_{q_1+q_2}}^{i_1...i_{p_1}...i_{p_1+p_2}} = T_{j_1...j_{q_1}}^{i_1...i_{p_1}} S_{j_{q_1+1}...j_{q_1+q_2}}^{i_{p_1+1}...i_{p_1+p_2}}.", "ticket": "3", "section": "3.4", "title": "Тензорное произведение."}, {"id": "1793287075637", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Перестановка аргументов тензора. (Билет 3.5)", "answerHtml": " Если индексов (верхних или нижних) больше чем 2, то при перестановке двух индексов надо зафиксировать их позиции. Можно также подвергнуть все верхние или нижние индексы произвольной (фиксированной) перестановке.", "questionText": "Перестановка аргументов тензора. (Билет 3.5)", "answerText": "Если индексов (верхних или нижних) больше чем 2, то при перестановке двух индексов надо зафиксировать их позиции. Можно также подвергнуть все верхние или нижние индексы произвольной (фиксированной) перестановке.", "ticket": "3", "section": "3.5", "title": "Перестановка аргументов тензора."}, {"id": "1793287075638", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Симметричные тензоры. (Билет 3.5)", "answerHtml": " Говорят, что тензор T симметричен по паре индексов (верхних или нижних), если при их перестановке он не меняется. Говорят, что тензор полностью симметричен (или просто симметричен) по верхним (аналогично — по нижним) индексам, если он не меняется при любой их перестановке.", "questionText": "Симметричные тензоры. (Билет 3.5)", "answerText": "Говорят, что тензор T симметричен по паре индексов (верхних или нижних), если при их перестановке он не меняется. Говорят, что тензор полностью симметричен (или просто симметричен) по верхним (аналогично — по нижним) индексам, если он не меняется при любой их перестановке.", "ticket": "3", "section": "3.5", "title": "Симметричные тензоры."}, {"id": "1793287075639", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Кососимметричные тензоры. (Билет 3.5)", "answerHtml": " Говорят, что тензор T кососимметричен по паре индексов (верхних или нижних), если при их перестановке он умножается на (−1). Говорят, что тензор полностью кососимметричен (или просто кососимметричен) по верхним (аналогично — по нижним) индексам, если при перестановке он умножается на знак перестановки.", "questionText": "Кососимметричные тензоры. (Билет 3.5)", "answerText": "Говорят, что тензор T кососимметричен по паре индексов (верхних или нижних), если при их перестановке он умножается на (−1). Говорят, что тензор полностью кососимметричен (или просто кососимметричен) по верхним (аналогично — по нижним) индексам, если при перестановке он умножается на знак перестановки.", "ticket": "3", "section": "3.5", "title": "Кососимметричные тензоры."}, {"id": "1793287075640", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Действие линейных отображений пространств на тензоры. (Билет 3.6)", "answerHtml": " Линейное отображение H_1 → H_2 индуцирует отображение пространства тензоров типа (0, k) на пространстве H_2 в пространство тензоров того же типа на H_1 и отображение пространства тензоров типа (k, 0) на H_1 в пространство тензоров того же типа на H_2.", "questionText": "Действие линейных отображений пространств на тензоры. (Билет 3.6)", "answerText": "Линейное отображение H_1 → H_2 индуцирует отображение пространства тензоров типа (0, k) на пространстве H_2 в пространство тензоров того же типа на H_1 и отображение пространства тензоров типа (k, 0) на H_1 в пространство тензоров того же типа на H_2.", "ticket": "3", "section": "3.6", "title": "Действие линейных отображений пространств на тензоры."}, {"id": "1793287075641", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Действие гладких отображений многообразий на тензоры (тензорные поля). (Билет 3.7)", "answerHtml": " Гладкое отображение F: M^n → N^m определяет отображение dF^* пространства тензорных полей типа (0, k) на многообразии N^m в пространство тензорных полей того же типа на многообразии M^n. Оно определяется так: dF^T(v_(1), ..., v_(k)) = T(dF v_(1), ..., dF v_(k)).", "questionText": "Действие гладких отображений многообразий на тензоры (тензорные поля). (Билет 3.7)", "answerText": "Гладкое отображение F: M^n → N^m определяет отображение dF^* пространства тензорных полей типа (0, k) на многообразии N^m в пространство тензорных полей того же типа на многообразии M^n. Оно определяется так: dF^T(v_(1), ..., v_(k)) = T(dF v_(1), ..., dF v_(k)).", "ticket": "3", "section": "3.7", "title": "Действие гладких отображений многообразий на тензоры (тензорные поля)."}, {"id": "1793287075642", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Кососимметрические тензоры типа (0,q) и их свойства. (Билет 3.8)", "answerHtml": " Кососимметричные тензоры типа (0, k) образуют пространство. Внешние произведения dx^{i_1} ∧ ... ∧ dx^{i_k} с i_1 < ... < i_k образуют базис в пространстве кососимметричных тензоров типа (0, k). Любой кососимметричный тензор ω однозначно записывается в виде ω = Σ_{i_1<...<i_k} ω_{i_1...i_k} · dx^{i_1} ∧ ... ∧ dx^{i_k}.", "questionText": "Кососимметрические тензоры типа (0,q) и их свойства. (Билет 3.8)", "answerText": "Кососимметричные тензоры типа (0, k) образуют пространство. Внешние произведения dx^{i_1} ∧ ... ∧ dx^{i_k} с i_1 < ... < i_k образуют базис в пространстве кососимметричных тензоров типа (0, k). Любой кососимметричный тензор ω однозначно записывается в виде ω = Σ_{i_1<...<i_k} ω_{i_1...i_k} · dx^{i_1} ∧ ... ∧ dx^{i_k}.", "ticket": "3", "section": "3.8", "title": "Кососимметрические тензоры типа (0,q) и их свойства."}, {"id": "1793287075643", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Внешнее произведение кососимметрических тензоров. (Билет 3.9)", "answerHtml": " Внешним произведением кососимметричных тензоров T и S называется тензор T ∧ S типа (0, k + l), компоненты которого определяются формулой (T ∧ S){i_1...i{k+l}} = (1/(k! l!)) Σ_σ sign σ · T_{i_{σ(1)}...i_{σ(k)}} · S_{i_{σ(k+1)}...i_{σ(k+l)}}, где суммирование ведется по всем перестановкам σ.", "questionText": "Внешнее произведение кососимметрических тензоров. (Билет 3.9)", "answerText": "Внешним произведением кососимметричных тензоров T и S называется тензор T ∧ S типа (0, k + l), компоненты которого определяются формулой (T ∧ S){i_1...i{k+l}} = (1/(k! l!)) Σ_σ sign σ · T_{i_{σ(1)}...i_{σ(k)}} · S_{i_{σ(k+1)}...i_{σ(k+l)}}, где суммирование ведется по всем перестановкам σ.", "ticket": "3", "section": "3.9", "title": "Внешнее произведение кососимметрических тензоров."}, {"id": "1793287075644", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Дифференциальные формы на многообразии. (Билет 4.1)", "answerHtml": " Кососимметричные тензорные поля типа (0, k) обычно называются дифференциальными k-формами.", "questionText": "Дифференциальные формы на многообразии. (Билет 4.1)", "answerText": "Кососимметричные тензорные поля типа (0, k) обычно называются дифференциальными k-формами.", "ticket": "4", "section": "4.1", "title": "Дифференциальные формы на многообразии."}, {"id": "1793287075645", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Координатная запись дифференциальных форм. (Билет 4.2)", "answerHtml": " В локальных координатах дифференциальная k-форма записывается в виде ω = Σ_{i_1<...<i_k} ω_{i_1...i_k} · dx^{i_1} ∧ ... ∧ dx^{i_k}, где коэффициенты ω_{i_1...i_k} являются функциями от точки.", "questionText": "Координатная запись дифференциальных форм. (Билет 4.2)", "answerText": "В локальных координатах дифференциальная k-форма записывается в виде ω = Σ_{i_1<...<i_k} ω_{i_1...i_k} · dx^{i_1} ∧ ... ∧ dx^{i_k}, где коэффициенты ω_{i_1...i_k} являются функциями от точки.", "ticket": "4", "section": "4.2", "title": "Координатная запись дифференциальных форм."}, {"id": "1793287075646", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Внешнее произведение дифференциальных форм. Его свойства. (Билет 4.3)", "answerHtml": " 1) T ∧ S — кососимметричный тензор", "questionText": "Внешнее произведение дифференциальных форм. Его свойства. (Билет 4.3)", "answerText": "1) T ∧ S — кососимметричный тензор", "ticket": "4", "section": "4.3", "title": "Внешнее произведение дифференциальных форм. Его свойства."}, {"id": "1793287075647", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Внешний дифференциал. Определение. (Билет 4.4)", "answerHtml": " Внешним дифференциалом дифференциальной k-формы ω = Σ_{i_1<...<i_k} ω_{i_1...i_k} · dx^{i_1} ∧ ... ∧ dx^{i_k} называется dω = Σ_{i_1<...<i_k} dω_{i_1...i_k} ∧ dx^{i_1} ∧ ... ∧ dx^{i_k}.", "questionText": "Внешний дифференциал. Определение. (Билет 4.4)", "answerText": "Внешним дифференциалом дифференциальной k-формы ω = Σ_{i_1<...<i_k} ω_{i_1...i_k} · dx^{i_1} ∧ ... ∧ dx^{i_k} называется dω = Σ_{i_1<...<i_k} dω_{i_1...i_k} ∧ dx^{i_1} ∧ ... ∧ dx^{i_k}.", "ticket": "4", "section": "4.4", "title": "Внешний дифференциал. Определение."}, {"id": "1793287075648", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Внешний дифференциал. Координатная формула. (Билет 4.4)", "answerHtml": " dω = Σ_{i_1<...<i_k} (∂ω_{i_1...i_k}/∂x^j) · dx^j ∧ dx^{i_1} ∧ ... ∧ dx^{i_k} (здесь по индексу j производится суммирование).", "questionText": "Внешний дифференциал. Координатная формула. (Билет 4.4)", "answerText": "dω = Σ_{i_1<...<i_k} (∂ω_{i_1...i_k}/∂x^j) · dx^j ∧ dx^{i_1} ∧ ... ∧ dx^{i_k} (здесь по индексу j производится суммирование).", "ticket": "4", "section": "4.4", "title": "Внешний дифференциал. Координатная формула."}, {"id": "1793287075649", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Корректность определения внешнего дифференциала. (Билет 4.5)", "answerHtml": " Корректность определения (т. е. независимость от выбора системы координат) является частным случаем утверждения о коммутировании внешнего дифференцирования с операцией взятия обратного образа (F^ dω = dF^* ω).", "questionText": "Корректность определения внешнего дифференциала. (Билет 4.5)", "answerText": "Корректность определения (т. е. независимость от выбора системы координат) является частным случаем утверждения о коммутировании внешнего дифференцирования с операцией взятия обратного образа (F^ dω = dF^* ω).", "ticket": "4", "section": "4.5", "title": "Корректность определения внешнего дифференциала."}, {"id": "1793287075650", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Основные свойства внешнего дифференцирования. (Билет 4.6)", "answerHtml": " 1) d(ω ∧ η) = dω ∧ η + (−1)^k ω ∧ dη", "questionText": "Основные свойства внешнего дифференцирования. (Билет 4.6)", "answerText": "1) d(ω ∧ η) = dω ∧ η + (−1)^k ω ∧ dη", "ticket": "4", "section": "4.6", "title": "Основные свойства внешнего дифференцирования."}, {"id": "1793287075651", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Обратный образ дифференциальной формы при гладком отображении. (Билет 4.7)", "answerHtml": " Гладкое отображение F: M^n → N^m определяет отображение F^: Ω^k(N^m) → Ω^k(M^n) пространств дифференциальных форм на многообразии N^m в пространства дифференциальных форм на многообразии M^n.", "questionText": "Обратный образ дифференциальной формы при гладком отображении. (Билет 4.7)", "answerText": "Гладкое отображение F: M^n → N^m определяет отображение F^: Ω^k(N^m) → Ω^k(M^n) пространств дифференциальных форм на многообразии N^m в пространства дифференциальных форм на многообразии M^n.", "ticket": "4", "section": "4.7", "title": "Обратный образ дифференциальной формы при гладком отображении."}, {"id": "1793287075652", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Коммутирование внешнего дифференцирования с обратным образом. (Билет 4.8)", "answerHtml": " Отображение (или отображения) F^ коммутирует (или коммутируют) с внешним дифференцированием: F^d = dF^.", "questionText": "Коммутирование внешнего дифференцирования с обратным образом. (Билет 4.8)", "answerText": "Отображение (или отображения) F^ коммутирует (или коммутируют) с внешним дифференцированием: F^d = dF^.", "ticket": "4", "section": "4.8", "title": "Коммутирование внешнего дифференцирования с обратным образом."}, {"id": "1793287075653", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Ориентирующие атласы. (Билет 5.1)", "answerHtml": " Ориентирующим атласом на гладком многообразии M^n называется такой атлас {(U_α, Ψ_α)}, для которого все отображения замен координат Ψ_α ∘ Ψ_α^{−1} имеют положительные якобианы.", "questionText": "Ориентирующие атласы. (Билет 5.1)", "answerText": "Ориентирующим атласом на гладком многообразии M^n называется такой атлас {(U_α, Ψ_α)}, для которого все отображения замен координат Ψ_α ∘ Ψ_α^{−1} имеют положительные якобианы.", "ticket": "5", "section": "5.1", "title": "Ориентирующие атласы."}, {"id": "1793287075654", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Ориентация гладкого многообразия. (Билет 5.1)", "answerHtml": " Ориентацией гладкого многообразия называется выбор ориентирующего атласа (или класса эквивалентных ориентирующих атласов) на нем. Многообразие с его ориентацией называется ориентированным.", "questionText": "Ориентация гладкого многообразия. (Билет 5.1)", "answerText": "Ориентацией гладкого многообразия называется выбор ориентирующего атласа (или класса эквивалентных ориентирующих атласов) на нем. Многообразие с его ориентацией называется ориентированным.", "ticket": "5", "section": "5.1", "title": "Ориентация гладкого многообразия."}, {"id": "1793287075655", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Ориентируемые и неориентируемые многообразия. Примеры. (Билет 5.2)", "answerHtml": " Гладкое многообразие M^n ориентируемо, если на нем существует ориентирующий атлас. Пример ориентируемого: сфера S^n. Пример неориентируемого: лента Мебиуса (или проективное пространство RP^n при четном n).", "questionText": "Ориентируемые и неориентируемые многообразия. Примеры. (Билет 5.2)", "answerText": "Гладкое многообразие M^n ориентируемо, если на нем существует ориентирующий атлас. Пример ориентируемого: сфера S^n. Пример неориентируемого: лента Мебиуса (или проективное пространство RP^n при четном n).", "ticket": "5", "section": "5.2", "title": "Ориентируемые и неориентируемые многообразия. Примеры."}, {"id": "1793287075656", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Дифференциальные формы максимальной степени и ориентация. (Билет 5.3)", "answerHtml": " При замене координат коэффициент при внешнем произведении дифференциалов в n-форме умножается на якобиан замены координат. Если ориентировать область K (зафиксировать класс координат с положительным якобианом), интеграл формы по области K будет корректно определен.", "questionText": "Дифференциальные формы максимальной степени и ориентация. (Билет 5.3)", "answerText": "При замене координат коэффициент при внешнем произведении дифференциалов в n-форме умножается на якобиан замены координат. Если ориентировать область K (зафиксировать класс координат с положительным якобианом), интеграл формы по области K будет корректно определен.", "ticket": "5", "section": "5.3", "title": "Дифференциальные формы максимальной степени и ориентация."}, {"id": "1793287075657", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Многообразия с краем. (Билет 5.4)", "answerHtml": " Гладким многообразием с краем называется хаусдорфово топологическое пространство M^k со счетной базой вместе с классом эквивалентных атласов на нем, где картой называется гомеоморфизм Ψ: U → V открытого множества U на открытое множество V пространства R^k или полупространства R^k_{≤0}.", "questionText": "Многообразия с краем. (Билет 5.4)", "answerText": "Гладким многообразием с краем называется хаусдорфово топологическое пространство M^k со счетной базой вместе с классом эквивалентных атласов на нем, где картой называется гомеоморфизм Ψ: U → V открытого множества U на открытое множество V пространства R^k или полупространства R^k_{≤0}.", "ticket": "5", "section": "5.4", "title": "Многообразия с краем."}, {"id": "1793287075658", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Внутренние и граничные точки многообразия с краем. (Билет 5.5)", "answerHtml": " Точка x ∈ M^n гладкого многообразия с краем принадлежит краю, если в некоторой карте (U, Ψ) она переводится в точку с координатой x^1 = 0 (то есть лежит на границе полупространства).", "questionText": "Внутренние и граничные точки многообразия с краем. (Билет 5.5)", "answerText": "Точка x ∈ M^n гладкого многообразия с краем принадлежит краю, если в некоторой карте (U, Ψ) она переводится в точку с координатой x^1 = 0 (то есть лежит на границе полупространства).", "ticket": "5", "section": "5.5", "title": "Внутренние и граничные точки многообразия с краем."}, {"id": "1793287075659", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Край гладкого многообразия как гладкое многообразие без края. (Билет 5.6)", "answerHtml": " Множество ∂M^n точек многообразия M^n, принадлежащих его краю, называется краем. Край ∂M^n многообразия с краем сам является гладким многообразием размерности n − 1 без края.", "questionText": "Край гладкого многообразия как гладкое многообразие без края. (Билет 5.6)", "answerText": "Множество ∂M^n точек многообразия M^n, принадлежащих его краю, называется краем. Край ∂M^n многообразия с краем сам является гладким многообразием размерности n − 1 без края.", "ticket": "5", "section": "5.6", "title": "Край гладкого многообразия как гладкое многообразие без края."}, {"id": "1793287075660", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Ориентация края ориентированного многообразия. (Билет 5.7)", "answerHtml": " Репер v_1, ..., v_{n−1} на крае ∂M^n положительно ориентирован в том и только в том случае, когда репер v_0, v_1, ..., v_{n−1} на многообразии M^n положительно ориентирован, где v_0 — вектор внешней нормали.", "questionText": "Ориентация края ориентированного многообразия. (Билет 5.7)", "answerText": "Репер v_1, ..., v_{n−1} на крае ∂M^n положительно ориентирован в том и только в том случае, когда репер v_0, v_1, ..., v_{n−1} на многообразии M^n положительно ориентирован, где v_0 — вектор внешней нормали.", "ticket": "5", "section": "5.7", "title": "Ориентация края ориентированного многообразия."}, {"id": "1793287075661", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Определение разбиения единицы. (Билет 6.1)", "answerHtml": " Разбиением единицы, вписанным в покрытие {U_α}, называется такое семейство гладких функций {φ_α} на многообразии M^n, что: 1) 0 ≤ φ_α(x) ≤ 1", "questionText": "Определение разбиения единицы. (Билет 6.1)", "answerText": "Разбиением единицы, вписанным в покрытие {U_α}, называется такое семейство гладких функций {φ_α} на многообразии M^n, что: 1) 0 ≤ φ_α(x) ≤ 1", "ticket": "6", "section": "6.1", "title": "Определение разбиения единицы."}, {"id": "1793287075662", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Существование разбиения единицы, подчинённого открытому покрытию гладкого многообразия. (Билет 6.2)", "answerHtml": " Для любого покрытия {U_α} многообразия M^n существует вписанное в него разбиение единицы. (Теорема 5)", "questionText": "Существование разбиения единицы, подчинённого открытому покрытию гладкого многообразия. (Билет 6.2)", "answerText": "Для любого покрытия {U_α} многообразия M^n существует вписанное в него разбиение единицы. (Теорема 5)", "ticket": "6", "section": "6.2", "title": "Существование разбиения единицы, подчинённого открытому покрытию гладкого многообразия."}, {"id": "1793287075663", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Применение разбиения единицы для перехода от локальных конструкций к глобальным: примеры. (Билет 6.3)", "answerHtml": " Используется для определения интеграла n-формы по компактному ориентированному n-мерному многообразию, а также для доказательства существования римановой метрики, продолжения тензорных полей (функций, векторных полей, форм), теоремы о вложимости многообразия в аффинное пространство.", "questionText": "Применение разбиения единицы для перехода от локальных конструкций к глобальным: примеры. (Билет 6.3)", "answerText": "Используется для определения интеграла n-формы по компактному ориентированному n-мерному многообразию, а также для доказательства существования римановой метрики, продолжения тензорных полей (функций, векторных полей, форм), теоремы о вложимости многообразия в аффинное пространство.", "ticket": "6", "section": "6.3", "title": "Применение разбиения единицы для перехода от локальных конструкций к глобальным: примеры."}, {"id": "1793287075664", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Интегрирование дифференциальных форм максимальной степени в координатной карте. (Билет 7.1)", "answerHtml": " Для формы ω = f(x) · dx^1 ∧ ... ∧ dx^n интеграл по области K в координатной окрестности определяется формулой ∫...∫ f(x) dx^1...dx^n.", "questionText": "Интегрирование дифференциальных форм максимальной степени в координатной карте. (Билет 7.1)", "answerText": "Для формы ω = f(x) · dx^1 ∧ ... ∧ dx^n интеграл по области K в координатной окрестности определяется формулой ∫...∫ f(x) dx^1...dx^n.", "ticket": "7", "section": "7.1", "title": "Интегрирование дифференциальных форм максимальной степени в координатной карте."}, {"id": "1793287075665", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Формула замены переменных при интегрировании дифференциальных форм. (Билет 7.2)", "answerHtml": " При замене координат коэффициент n-формы умножается на якобиан замены координат. При интегрировании подынтегральная функция умножается на модуль якобиана, что обеспечивает независимость интеграла от выбора координат.", "questionText": "Формула замены переменных при интегрировании дифференциальных форм. (Билет 7.2)", "answerText": "При замене координат коэффициент n-формы умножается на якобиан замены координат. При интегрировании подынтегральная функция умножается на модуль якобиана, что обеспечивает независимость интеграла от выбора координат.", "ticket": "7", "section": "7.2", "title": "Формула замены переменных при интегрировании дифференциальных форм."}, {"id": "1793287075666", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Интеграл формы по ориентированному многообразию. (Билет 7.3)", "answerHtml": " Интегралом ∫_{M^n} ω формы ω по многообразию M^n называется сумма Σ_{i=1}^N ∫_{M^n} φ_i ω, где {φ_i} — конечное разбиение единицы, вписанное в покрытие {U_i} ориентирующего атласа.", "questionText": "Интеграл формы по ориентированному многообразию. (Билет 7.3)", "answerText": "Интегралом ∫_{M^n} ω формы ω по многообразию M^n называется сумма Σ_{i=1}^N ∫_{M^n} φ_i ω, где {φ_i} — конечное разбиение единицы, вписанное в покрытие {U_i} ориентирующего атласа.", "ticket": "7", "section": "7.3", "title": "Интеграл формы по ориентированному многообразию."}, {"id": "1793287075667", "deckId": "1793286881161", "deck": "многообразия", "questionHtml": "Независимость интеграла от выбора координатных карт и разбиения единицы. (Билет 7.4)", "answerHtml": " Определение интеграла формы ω по многообразию M^n корректно, т. е. не зависит от выбора атласа {(U_i, Ψ_i)} и разбиения единицы {φ_i}. (Доказывается через аддитивность интеграла и свойство Σ φ_i = 1).", "questionText": "Независимость интеграла от выбора координатных карт и разбиения единицы. (Билет 7.4)", "answerText": "Определение интеграла формы ω по многообразию M^n корректно, т. е. не зависит от выбора атласа {(U_i, Ψ_i)} и разбиения единицы {φ_i}. (Доказывается через аддитивность интеграла и свойство Σ φ_i = 1).", "ticket": "7", "section": "7.4", "title": "Независимость интеграла от выбора координатных карт и разбиения единицы."}], "tickets": [{"id": "1", "title": "Билет 1", "sections": ["1.1", "1.2", "1.3", "1.4"], "cardIds": ["1793287075604", "1793287075605", "1793287075606", "1793287075607", "1793287075608", "1793287075609", "1793287075610"]}, {"id": "2", "title": "Билет 2", "sections": ["2.1", "2.2", "2.3", "2.4", "2.5", "2.6", "2.7", "2.8", "2.9", "2.10", "2.11"], "cardIds": ["1793287075611", "1793287075612", "1793287075613", "1793287075614", "1793287075615", "1793287075616", "1793287075617", "1793287075618", "1793287075619", "1793287075620", "1793287075621", "1793287075622", "1793287075623", "1793287075624", "1793287075625", "1793287075626", "1793287075627", "1793287075628", "1793287075629", "1793287075630"]}, {"id": "3", "title": "Билет 3", "sections": ["3.1", "3.2", "3.3", "3.4", "3.5", "3.6", "3.7", "3.8", "3.9"], "cardIds": ["1793287075631", "1793287075632", "1793287075633", "1793287075634", "1793287075635", "1793287075636", "1793287075637", "1793287075638", "1793287075639", "1793287075640", "1793287075641", "1793287075642", "1793287075643"]}, {"id": "4", "title": "Билет 4", "sections": ["4.1", "4.2", "4.3", "4.4", "4.5", "4.6", "4.7", "4.8"], "cardIds": ["1793287075644", "1793287075645", "1793287075646", "1793287075647", "1793287075648", "1793287075649", "1793287075650", "1793287075651", "1793287075652"]}, {"id": "5", "title": "Билет 5", "sections": ["5.1", "5.2", "5.3", "5.4", "5.5", "5.6", "5.7"], "cardIds": ["1793287075653", "1793287075654", "1793287075655", "1793287075656", "1793287075657", "1793287075658", "1793287075659", "1793287075660"]}, {"id": "6", "title": "Билет 6", "sections": ["6.1", "6.2", "6.3"], "cardIds": ["1793287075661", "1793287075662", "1793287075663"]}, {"id": "7", "title": "Билет 7", "sections": ["7.1", "7.2", "7.3", "7.4"], "cardIds": ["1793287075664", "1793287075665", "1793287075666", "1793287075667"]}]};
